// Componente PrevMascot — persona humana da Prev
// A imagem é a persona ilustrada gerada para o assistente virtual do Agros.

const PERSONA_SRC = "data:image/png;base64,";

interface PrevMascotProps {
  size?: number;
  className?: string;
}

export const PrevMascot = ({ size = 80, className = "" }: PrevMascotProps) => (
  <img
    src={PERSONA_SRC}
    alt="Prev — assistente virtual do Agros"
    width={size}
    height={size}
    className={`rounded-full object-cover object-top ${className}`}
    style={{ width: size, height: size }}
  />
);
